components.css:
.ds-primary { display: inline-flex; align-items: center; gap: 7px; border: 0; border-radius: 24px; padding: 9px 15px; min-height: 41px; font: 620 14px/1.45 "Inter Variable", "Inter", system-ui, sans-serif; color: var(--panel, #fff); background: var(--dark, #262520); cursor: pointer; white-space: nowrap; }
.ds-primary:hover { background: #48443b; }
.ds-primary:focus-visible { outline: 2px solid var(--rust, #9c3219); outline-offset: 4px; }

.ds-secondary { border: 1px solid var(--line, #e9e7e4); border-radius: 20px; padding: 7px 12px; font: 620 .78rem/1.45 "Inter Variable", "Inter", system-ui, sans-serif; color: var(--ink, #262520); background: var(--panel, #fff); cursor: pointer; white-space: nowrap; }
.ds-secondary:hover { background: var(--soft, #f4f3f1); }
.ds-secondary:focus-visible { outline: 2px solid var(--rust, #9c3219); outline-offset: 4px; }

.ds-text-button { display: inline-flex; align-items: center; gap: 7px; border: 0; padding: 5px 0; font: 620 .79rem/1.45 "Inter Variable", "Inter", system-ui, sans-serif; color: var(--rust, #9c3219); background: transparent; cursor: pointer; white-space: nowrap; }
.ds-text-button:hover { text-decoration: underline; text-underline-offset: 3px; }
.ds-text-button:focus-visible { outline: 2px solid var(--rust, #9c3219); outline-offset: 4px; }

.ds-balance-link { display: inline-flex; align-items: center; justify-content: center; gap: 7px; width: fit-content; border: 0; border-radius: 20px; padding: 7px 12px; font: 620 .79rem/1.45 "Inter Variable", "Inter", system-ui, sans-serif; color: #381e15; background: #fff3ed; cursor: pointer; white-space: nowrap; }
.ds-balance-link:hover { background: var(--panel, #fff); }
.ds-balance-link:focus-visible { outline: 2px solid var(--rust, #9c3219); outline-offset: 4px; }

.ds-search { display: inline-flex; align-items: center; gap: 6px; border: 1px solid #dbd8d3; border-radius: 9px; padding-left: 8px; color: var(--muted, #605e58); }
.ds-search input { width: 145px; border: 0; min-width: 0; padding: 6px 7px 6px 0; font: 400 .75rem/1.45 "Inter Variable", "Inter", system-ui, sans-serif; color: var(--ink, #262520); background: transparent; }
.ds-search input::placeholder { color: var(--muted, #605e58); }
.ds-search:focus-within { outline: 2px solid var(--rust, #9c3219); outline-offset: 2px; }
.ds-search input:focus { outline: 0; }

.ds-nav { display: flex; flex-direction: column; gap: 3px; width: 130px; border-radius: 16px; padding: 6px; background: var(--panel, #fff); }
.ds-nav button { display: flex; align-items: center; gap: 8px; padding: 11px 9px; border: 0; border-radius: 10px; background: transparent; color: var(--muted, #605e58); font: 570 .81rem/1.45 "Inter Variable", "Inter", system-ui, sans-serif; cursor: pointer; text-align: left; white-space: nowrap; }
.ds-nav button:hover { background: var(--soft, #f4f3f1); }
.ds-nav button[aria-current] { background: var(--dark, #262520); color: var(--panel, #fff); }
.ds-nav button:focus-visible { outline: 2px solid var(--rust, #9c3219); outline-offset: 4px; }

.ds-metric { display: flex; flex-direction: column; gap: 4px; padding: 13px; border: 1px solid #efeeeb; border-radius: var(--radius, 16px); background: var(--panel, #fff); color: var(--ink, #262520); font: 400 14px/1.45 "Inter Variable", "Inter", system-ui, sans-serif; font-variant-numeric: tabular-nums; }
.ds-metric > div { display: flex; justify-content: space-between; align-items: flex-start; gap: 4px; }
.ds-metric h2, .ds-metric p { margin: 0; }
.ds-metric h2 { font-size: .78rem; line-height: 1.18; font-weight: 650; letter-spacing: -.01em; }
.ds-metric svg { color: var(--rust, #9c3219); }
.ds-metric strong { padding-top: 12px; font-size: 1.14rem; font-weight: 650; letter-spacing: -.035em; line-height: 1.2; overflow-wrap: anywhere; }
.ds-metric p { font-size: .72rem; color: var(--muted, #605e58); }

.ds-balance { display: flex; flex-direction: column; padding: 17px; border-radius: var(--radius, 16px); background: linear-gradient(145deg, var(--peach, #ff9569), var(--orange, #ec5329) 88%); color: #24150f; font: 400 14px/1.45 "Inter Variable", "Inter", system-ui, sans-serif; font-variant-numeric: tabular-nums; }
.ds-balance-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.ds-balance-head h2 { margin: 0; font-size: 1rem; font-weight: 650; line-height: 1.18; letter-spacing: -.025em; }
.ds-balance-head span { display: inline-flex; align-items: center; gap: 4px; padding: 4px 8px; border-radius: 14px; background: #fff3ed; font-size: .72rem; font-weight: 650; }
.ds-balance > strong { margin: 8px 0 2px; font-size: 2rem; font-weight: 650; line-height: 1.08; letter-spacing: -.035em; overflow-wrap: anywhere; }
.ds-balance > p { margin: 0; font-size: .78rem; }
.ds-balance-account { display: flex; align-items: center; gap: 9px; margin: 9px 0; border-top: 1px solid #3d170c32; padding: 9px 0; font-size: .82rem; }
.ds-balance-account > span { display: grid; place-items: center; min-width: 29px; height: 29px; border-radius: 50%; background: #fff0e8; color: #46261b; font-size: .75rem; font-weight: 700; }
.ds-balance-account > div { display: grid; gap: 2px; min-width: 0; flex: 1; }
.ds-balance-account small { color: #372019; font-size: .75rem; }
.ds-balance-account b { font-weight: 650; }
.ds-balance button { display: inline-flex; align-items: center; gap: 7px; align-self: start; border: 0; border-radius: 20px; padding: 7px 12px; background: #fff3ed; color: #381e15; font: 620 .79rem/1.45 "Inter Variable", "Inter", system-ui, sans-serif; cursor: pointer; }
.ds-balance button:hover { background: var(--panel, #fff); }
.ds-balance button:focus-visible { outline: 2px solid var(--rust, #9c3219); outline-offset: 4px; }

.ds-credit-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(150px, 100%), 1fr)); gap: 9px; }
.ds-credit { display: grid; gap: 12px; min-height: 122px; border-radius: 12px; padding: 12px; background: var(--dark, #262520); color: var(--panel, #fff); font: 400 14px/1.45 "Inter Variable", "Inter", system-ui, sans-serif; font-variant-numeric: tabular-nums; }
.ds-credit:nth-child(even) { background: var(--peach, #ff9569); color: #24150f; }
.ds-credit > div { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 6px; font-size: .73rem; }
.ds-credit h3 { margin: 0; font-size: .93rem; font-weight: 620; line-height: 1.18; letter-spacing: -.025em; overflow-wrap: anywhere; }
.ds-credit p { margin: 3px 0 0; font-size: .76rem; }
.ds-credit small { font-size: .75rem; }
.ds-credit b { font-weight: 650; }
